import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const group = new Group();

  // ---------- Plane (backdrop) ----------
  const atlasRect = { x: 0, y: 0, width: 512, height: 320 };
  const aspect = atlasRect.width / atlasRect.height; // 1.6
  const planeGeom = new PlaneGeometry(aspect, 1);
  const planeMat = new MeshBasicNodeMaterial();
  const planeMesh = new Mesh(planeGeom, planeMat);
  group.add(planeMesh);

  // Load texture asynchronously, keep function synchronous
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = texture(tex);
      planeMat.needsUpdate = true;
    });
  }

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textColor = (config.intent?.visualSpec?.colors?.paper) ?? '#e8ecf2';
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: textColor,
      align: 'center',
    });
    // Position text slightly in front of the plane to avoid Z‑fight
    txt.position.set(0, 0, 0.01);
    group.add(txt);
  }

  // ---------- Cinematic Primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const primitive = ctx.primitives[prim.name];
      if (primitive) {
        const instance = primitive(group, prim.params);
        // store for cleanup
        if (!group.userData._primitiveInstances) group.userData._primitiveInstances = [];
        group.userData._primitiveInstances.push(instance);
      }
    }
  }

  // ---------- Event Handlers ----------
  group.userData.handlers = {};

  // ---------- Cleanup ----------
  const timelines = []; // any GSAP timelines would be pushed here
  group.userData.cleanup = () => {
    // dispose geometry & material
    planeGeom.dispose();
    planeMat.dispose();

    // cleanup primitives
    if (group.userData._primitiveInstances) {
      for (const p of group.userData._primitiveInstances) {
        if (p.cleanup) p.cleanup();
      }
    }

    // kill GSAP timelines
    for (const tl of timelines) tl.kill();
  };

  return group;
}
